insert into public.retos
  (nivel_id, orden, tipo, enunciado, codigo, opciones, respuesta, explicacion_correcta, explicacion_error, pista)
values
(1, 1, 'mazmorra', 'El Pasillo de la Aldea', null, '{"nombre":"El Pasillo de la Aldea","historia":"Tu primer encargo: cruza el pasillo y sal por la puerta. Un algoritmo es una lista de pasos en orden.","modo":"bloques","mapa":["######","#S.C.#","####.#","####P#"],"direccionInicial":"este","energia":11,"instrucciones":["adelante","girar_izquierda","girar_derecha","recoger"],"objetivosExtra":[{"tipo":"monedas"},{"tipo":"maxInstrucciones","valor":7}],"objeto":"botas_veloces","pista":"Avanza hasta el fondo del pasillo, gira a la derecha y baja hasta la puerta."}'::jsonb, '{"solucion":"adelante()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\nadelante()","solucionExtras":"adelante()\nadelante()\nrecoger()\nadelante()\ngirar_derecha()\nadelante()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Avanza hasta el fondo del pasillo, gira a la derecha y baja hasta la puerta.'),
(2, 1, 'mazmorra', 'El Patio de los Giros', null, '{"nombre":"El Patio de los Giros","historia":"Si giras en el momento equivocado chocarás con los muros. El orden de los pasos importa.","modo":"bloques","mapa":["#######","#S..#.#","##g.#.#","###...#","#####P#"],"direccionInicial":"este","energia":17,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar"],"objetivosExtra":[{"tipo":"sinChoques"},{"tipo":"derrotarTodos"}],"objeto":"daga_madera","pista":"Baja por el pasillo del medio. El goblin está a la izquierda cuando bajas: gira para mirarlo y ataca."}'::jsonb, '{"solucion":"adelante()\nadelante()\ngirar_derecha()\nadelante()\nadelante()\ngirar_izquierda()\nadelante()\nadelante()\ngirar_derecha()\nadelante()","solucionExtras":"adelante()\nadelante()\ngirar_derecha()\nadelante()\ngirar_derecha()\natacar()\ngirar_izquierda()\nadelante()\ngirar_izquierda()\nadelante()\nadelante()\ngirar_derecha()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Baja por el pasillo del medio. El goblin está a la izquierda cuando bajas: gira para mirarlo y ataca.'),
(3, 1, 'mazmorra', 'La Guarida del Goblin Jefe', null, '{"nombre":"La Guarida del Goblin Jefe","historia":"Un problema grande se resuelve en partes: primero el pasillo de arriba, luego el de abajo.","modo":"bloques","mapa":["########","#S.g..C#","######.#","#P..g..#","########"],"direccionInicial":"este","energia":21,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","recoger"],"objetivosExtra":[{"tipo":"monedas"},{"tipo":"sinDanio"}],"objeto":"cota_cuero","pista":"Ataca a cada goblin antes de que te bloquee el paso: si caminas hacia él, te golpea."}'::jsonb, '{"solucion":"adelante()\natacar()\nadelante()\nadelante()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\natacar()\nadelante()\nadelante()\nadelante()\nadelante()","solucionExtras":"adelante()\natacar()\nadelante()\nadelante()\nadelante()\nadelante()\nrecoger()\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\natacar()\nadelante()\nadelante()\nadelante()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Ataca a cada goblin antes de que te bloquee el paso: si caminas hacia él, te golpea.'),
(4, 1, 'mazmorra', 'El Cofre Contador', null, '{"nombre":"El Cofre Contador","historia":"Una variable es una caja con nombre que guarda un número. Usa pasos = 2 y repítelo.","modo":"bloques","mapa":["########","#S.C.C.#","######.#","#P.....#","########"],"direccionInicial":"este","energia":20,"instrucciones":["adelante","girar_izquierda","girar_derecha","recoger","variable","repetir"],"objetivosExtra":[{"tipo":"maxInstrucciones","valor":13},{"tipo":"monedas"}],"objeto":"anillo_mana","pista":"Las monedas están cada 2 pasos. Guarda ese 2 en una variable y repite \"avanzar 2 y recoger\"."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nREPETIR 5 VECES\n  adelante()\nFIN","solucionExtras":"pasos = 2\nREPETIR pasos VECES\n  adelante()\n  adelante()\n  recoger()\nFIN\nadelante()\ngirar_derecha()\nREPETIR 2 VECES\n  adelante()\nFIN\ngirar_derecha()\nlargo = 5\nREPETIR largo VECES\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Las monedas están cada 2 pasos. Guarda ese 2 en una variable y repite "avanzar 2 y recoger".'),
(5, 1, 'mazmorra', 'El Sendero de Pinchos', null, '{"nombre":"El Sendero de Pinchos","historia":"No todo se resuelve igual: el piso se camina, los pinchos se saltan y los goblins se atacan.","modo":"bloques","mapa":["########","#S^.C^.#","######g#","######.#","######P#"],"direccionInicial":"este","energia":14,"instrucciones":["adelante","girar_izquierda","girar_derecha","saltar","atacar","recoger"],"objetivosExtra":[{"tipo":"sinDanio"},{"tipo":"monedas"}],"objeto":"capa_viajero","pista":"Usa saltar() delante de cada pincho para no lastimarte."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\natacar()\nREPETIR 3 VECES\n  adelante()\nFIN","solucionExtras":"saltar()\nadelante()\nrecoger()\nsaltar()\ngirar_derecha()\natacar()\nREPETIR 3 VECES\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Usa saltar() delante de cada pincho para no lastimarte.'),
(6, 1, 'mazmorra', 'La Cripta del Esqueleto', null, '{"nombre":"La Cripta del Esqueleto","historia":"Un caballero esqueleto custodia la cripta. Cambia el valor de tu variable para cada tramo.","modo":"bloques","mapa":["########","#S.C...#","###.##.#","###k##P#","########"],"direccionInicial":"este","energia":20,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","variable","repetir"],"objetivosExtra":[{"tipo":"derrotarTodos"},{"tipo":"maxInstrucciones","valor":17}],"objeto":"espada_bronce","pista":"El caballero tiene 3 de vida y pega fuerte. Con la Daga de madera lo vences en 2 golpes."}'::jsonb, '{"solucion":"pasos = 5\nREPETIR pasos VECES\n  adelante()\nFIN\ngirar_derecha()\npasos = 2\nREPETIR pasos VECES\n  adelante()\nFIN","solucionExtras":"pasos = 2\nREPETIR pasos VECES\n  adelante()\nFIN\ngirar_derecha()\nadelante()\nREPETIR 2 VECES\n  atacar()\nFIN\ngirar_derecha()\ngirar_derecha()\nadelante()\ngirar_derecha()\npasos = 3\nREPETIR pasos VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 2 VECES\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'El caballero tiene 3 de vida y pega fuerte. Con la Daga de madera lo vences en 2 golpes.'),
(7, 1, 'mazmorra', 'La Bifurcación', null, '{"nombre":"La Bifurcación","historia":"No sabes dónde aparecen los goblins. Pregunta antes de avanzar: SI hay_enemigo ENTONCES atacar().","modo":"mixto","mapa":["########","#S.g.gC#","######.#","######P#"],"direccionInicial":"este","energia":15,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","recoger","repetir","si"],"objetivosExtra":[{"tipo":"sinChoques"},{"tipo":"monedas"}],"objeto":"pergamino_sabio","pista":"Repite 5 veces: si hay un enemigo enfrente, ataca; después avanza."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\ngirar_derecha()\nadelante()\nadelante()","solucionExtras":"REPETIR 5 VECES\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\nrecoger()\ngirar_derecha()\nadelante()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Repite 5 veces: si hay un enemigo enfrente, ataca; después avanza.'),
(8, 1, 'mazmorra', 'El Puente Dudoso', null, '{"nombre":"El Puente Dudoso","historia":"En el puente hay tablas rotas con pinchos. Si hay pincho, salta; si no, camina.","modo":"mixto","mapa":["########","#S.^.^.#","######o#","######P#"],"direccionInicial":"este","energia":12,"instrucciones":["adelante","girar_izquierda","girar_derecha","saltar","atacar","repetir","si","sino"],"objetivosExtra":[{"tipo":"sinDanio"},{"tipo":"maxInstrucciones","valor":8}],"objeto":"casco_hierro","pista":"Usa SI hay_pincho ENTONCES saltar() SINO adelante() dentro de un REPETIR."}'::jsonb, '{"solucion":"REPETIR 3 VECES\n  SI hay_pincho ENTONCES\n    saltar()\n  SINO\n    adelante()\n  FIN\nFIN\ngirar_derecha()\natacar()\natacar()\nadelante()\nadelante()","solucionExtras":"REPETIR 3 VECES\n  SI hay_pincho ENTONCES\n    saltar()\n  SINO\n    adelante()\n  FIN\nFIN\ngirar_derecha()\natacar()\nadelante()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Usa SI hay_pincho ENTONCES saltar() SINO adelante() dentro de un REPETIR.'),
(9, 1, 'mazmorra', 'El Torreón de las Decisiones', null, '{"nombre":"El Torreón de las Decisiones","historia":"Un orco cierra el paso y un caballero guarda un rincón. Decide a quién enfrentar.","modo":"mixto","mapa":["########","#S.o..C#","##.###.#","##k###.#","######P#"],"direccionInicial":"este","energia":21,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","recoger","repetir","si","sino"],"objetivosExtra":[{"tipo":"derrotarTodos"},{"tipo":"monedas"}],"objeto":"lanza_larga","pista":"El caballero está bajando desde la segunda casilla. Necesitas ataque 2 y algo de armadura para vencerlo."}'::jsonb, '{"solucion":"adelante()\nREPETIR 2 VECES\n  atacar()\nFIN\nREPETIR 4 VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 3 VECES\n  adelante()\nFIN","solucionExtras":"adelante()\ngirar_derecha()\nadelante()\nREPETIR 2 VECES\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\nFIN\ngirar_derecha()\ngirar_derecha()\nadelante()\ngirar_derecha()\nREPETIR 4 VECES\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\nrecoger()\ngirar_derecha()\nREPETIR 3 VECES\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'El caballero está bajando desde la segunda casilla. Necesitas ataque 2 y algo de armadura para vencerlo.'),
(10, 1, 'mazmorra', 'El Túnel Largo', null, '{"nombre":"El Túnel Largo","historia":"El túnel da vueltas y vueltas. Escribe REPETIR N VECES para no copiar la misma línea.","modo":"texto","mapa":["########","#S.....#","######.#","#C.....#","#.######","#.....P#","########"],"direccionInicial":"este","energia":28,"instrucciones":["adelante","girar_izquierda","girar_derecha","recoger","repetir"],"objetivosExtra":[{"tipo":"maxInstrucciones","valor":15},{"tipo":"monedas"}],"objeto":"lupa_explorador","pista":"Cada tramo largo mide 5 casillas y cada tramo corto mide 2."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 2 VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 5 VECES\n  adelante()\nFIN\ngirar_izquierda()\nREPETIR 2 VECES\n  adelante()\nFIN\ngirar_izquierda()\nREPETIR 5 VECES\n  adelante()\nFIN","solucionExtras":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 2 VECES\n  adelante()\nFIN\ngirar_derecha()\nREPETIR 5 VECES\n  adelante()\nFIN\nrecoger()\ngirar_izquierda()\nREPETIR 2 VECES\n  adelante()\nFIN\ngirar_izquierda()\nREPETIR 5 VECES\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Cada tramo largo mide 5 casillas y cada tramo corto mide 2.'),
(11, 1, 'mazmorra', 'El Río Sin Fin', null, '{"nombre":"El Río Sin Fin","historia":"No sabes cuánto mide la orilla. Repite MIENTRAS no haya muro enfrente.","modo":"texto","mapa":["########","#S.g..g#","######.#","#P.g...#","########"],"direccionInicial":"este","energia":21,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","mientras","si"],"objetivosExtra":[{"tipo":"maxInstrucciones","valor":12},{"tipo":"sinChoques"}],"objeto":"escudo_runico","pista":"MIENTRAS NO hay_muro HACER: si hay enemigo ataca, y luego avanza."}'::jsonb, '{"solucion":"MIENTRAS NO hay_muro HACER\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\ngirar_derecha()\nMIENTRAS NO hay_muro HACER\n  adelante()\nFIN\ngirar_derecha()\nMIENTRAS NO hay_muro HACER\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN","solucionExtras":"MIENTRAS NO hay_muro HACER\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\ngirar_derecha()\nMIENTRAS NO hay_muro HACER\n  adelante()\nFIN\ngirar_derecha()\nMIENTRAS NO hay_muro HACER\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'MIENTRAS NO hay_muro HACER: si hay enemigo ataca, y luego avanza.'),
(12, 1, 'mazmorra', 'La Galería de Cofres', null, '{"nombre":"La Galería de Cofres","historia":"Una fila de monedas es como una lista: recórrela una por una. Al fondo esperan un orco y un caballero.","modo":"texto","mapa":["########","#SCCCC.#","######.#","#k..o..#","#####P##"],"direccionInicial":"este","energia":31,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","recoger","repetir","mientras","si","sino"],"objetivosExtra":[{"tipo":"monedas"},{"tipo":"derrotarTodos"}],"objeto":"hacha_guerra","pista":"Recorre la fila con REPETIR 4 VECES adelante() y recoger(). Para el caballero lleva arma y escudo."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\ngirar_izquierda()\nadelante()","solucionExtras":"REPETIR 4 VECES\n  adelante()\n  recoger()\nFIN\nadelante()\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nMIENTRAS NO hay_muro HACER\n  SI hay_enemigo ENTONCES\n    atacar()\n  SINO\n    adelante()\n  FIN\nFIN\ngirar_derecha()\ngirar_derecha()\nREPETIR 4 VECES\n  adelante()\nFIN\ngirar_derecha()\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Recorre la fila con REPETIR 4 VECES adelante() y recoger(). Para el caballero lleva arma y escudo.'),
(13, 1, 'mazmorra', 'El Taller del Herrero', null, '{"nombre":"El Taller del Herrero","historia":"Los escalones del taller se repiten. Crea una FUNCION escalon() y úsala varias veces.","modo":"texto","mapa":["########","#S.#####","##..####","###.g###","####.g##","#####.P#","########"],"direccionInicial":"este","energia":23,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","repetir","si","funcion"],"objetivosExtra":[{"tipo":"maxInstrucciones","valor":10},{"tipo":"sinDanio"}],"objeto":"amuleto_vida","pista":"Un escalón es: avanzar, girar a la derecha, avanzar y girar a la izquierda. Antes de avanzar, revisa si hay enemigo."}'::jsonb, '{"solucion":"FUNCION escalon()\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\n  girar_derecha()\n  adelante()\n  girar_izquierda()\nFIN\nREPETIR 4 VECES\n  escalon()\nFIN\nadelante()","solucionExtras":"FUNCION escalon()\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\n  girar_derecha()\n  adelante()\n  girar_izquierda()\nFIN\nREPETIR 4 VECES\n  escalon()\nFIN\nadelante()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Un escalón es: avanzar, girar a la derecha, avanzar y girar a la izquierda. Antes de avanzar, revisa si hay enemigo.'),
(14, 1, 'mazmorra', 'Las Escaleras de la Fortaleza', null, '{"nombre":"Las Escaleras de la Fortaleza","historia":"Tu función tramo() camina tantas casillas como diga la variable largo: ese es su dato de entrada.","modo":"texto","mapa":["########","#S....C#","######.#","#..o...#","#.######","#P######"],"direccionInicial":"este","energia":23,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","recoger","variable","repetir","si","funcion"],"objetivosExtra":[{"tipo":"monedas"},{"tipo":"maxInstrucciones","valor":17}],"objeto":"armadura_placas","pista":"Cambia largo antes de llamar a tramo(): 5, luego 2, luego 5 y por último 2."}'::jsonb, '{"solucion":"REPETIR 5 VECES\n  adelante()\nFIN\ngirar_derecha()\nadelante()\nadelante()\ngirar_derecha()\nadelante()\nadelante()\natacar()\natacar()\nREPETIR 3 VECES\n  adelante()\nFIN\ngirar_izquierda()\nadelante()\nadelante()","solucionExtras":"largo = 5\nFUNCION tramo()\n  REPETIR largo VECES\n    SI hay_enemigo ENTONCES\n      atacar()\n    FIN\n    adelante()\n  FIN\nFIN\ntramo()\nrecoger()\ngirar_derecha()\nlargo = 2\ntramo()\ngirar_derecha()\nlargo = 5\ntramo()\ngirar_izquierda()\nlargo = 2\ntramo()"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Cambia largo antes de llamar a tramo(): 5, luego 2, luego 5 y por último 2.'),
(15, 1, 'mazmorra', 'El Trono del Rey Esqueleto', null, '{"nombre":"El Trono del Rey Esqueleto","historia":"El Rey Esqueleto espera en su trono. Usa todo lo que aprendiste: funciones, repeticiones y decisiones.","modo":"texto","mapa":["########","#S.o...#","#.####.#","#k####o#","######.#","######P#"],"direccionInicial":"este","energia":23,"instrucciones":["adelante","girar_izquierda","girar_derecha","atacar","repetir","mientras","si","sino","funcion","variable"],"objetivosExtra":[{"tipo":"derrotarTodos"},{"tipo":"sinDanio"}],"objeto":"espada_hierro","pista":"Con el Hacha de guerra cada enemigo cae de un golpe. El Rey está bajando desde la entrada."}'::jsonb, '{"solucion":"FUNCION avanzar_luchando()\n  SI hay_enemigo ENTONCES\n    atacar()\n    atacar()\n  FIN\n  adelante()\nFIN\nREPETIR 5 VECES\n  avanzar_luchando()\nFIN\ngirar_derecha()\nREPETIR 4 VECES\n  avanzar_luchando()\nFIN","solucionExtras":"FUNCION avanzar_luchando()\n  SI hay_enemigo ENTONCES\n    atacar()\n  FIN\n  adelante()\nFIN\ngirar_derecha()\nadelante()\natacar()\ngirar_derecha()\ngirar_derecha()\nadelante()\ngirar_derecha()\nREPETIR 5 VECES\n  avanzar_luchando()\nFIN\ngirar_derecha()\nREPETIR 4 VECES\n  avanzar_luchando()\nFIN"}'::jsonb, '¡Saliste de la mazmorra!', 'Tu hechizo no llegó a la puerta. Revisa el motivo y vuelve a intentarlo.', 'Con el Hacha de guerra cada enemigo cae de un golpe. El Rey está bajando desde la entrada.');
